package main

import "testing"

type fakeProcessImage struct {
	variable variableInfo
	value    byte
	writes   int
}

func (f *fakeProcessImage) Variable(string) (variableInfo, error) { return f.variable, nil }
func (f *fakeProcessImage) Read(offset uint32, destination []byte) (int, error) {
	destination[0] = f.value
	return 1, nil
}
func (f *fakeProcessImage) Write(offset uint32, source []byte) (int, error) {
	f.value = source[0]
	f.writes++
	return 1, nil
}
func (f *fakeProcessImage) Close() error { return nil }

func TestLEDDevicePreservesUnselectedLEDAndSkipsUnchangedWrite(t *testing.T) {
	image := &fakeProcessImage{variable: variableInfo{offset: 42, bits: 8}, value: 8}
	device, err := newLEDDevice(image, "A1")
	if err != nil {
		t.Fatal(err)
	}
	if err := device.SetColor(colorGreen); err != nil {
		t.Fatal(err)
	}
	if image.value != 9 || image.writes != 1 {
		t.Fatalf("value=%d writes=%d, want value 9 and one write", image.value, image.writes)
	}
	if err := device.SetColor(colorGreen); err != nil {
		t.Fatal(err)
	}
	if image.value != 9 || image.writes != 1 {
		t.Fatalf("unchanged value=%d writes=%d, want no second write", image.value, image.writes)
	}
}

func TestLEDDeviceRejectsUnexpectedRevPiLEDWidth(t *testing.T) {
	image := &fakeProcessImage{variable: variableInfo{offset: 42, bits: 16}}
	if _, err := newLEDDevice(image, "A1"); err == nil {
		t.Fatal("16-bit RevPiLED variable was accepted")
	}
}
